When you build a Blazor WebAssembly app, you're creating a client-side SPA that runs entirely in the browser.

But authentication needs a secure backend.

Here's what happens without proper setup:

```text
// ❌ This won't work in Blazor WASM - No server-side session
@inject AuthenticationStateProvider AuthStateProvider

@code {
    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        var user = authState.User;
        // user.Identity.IsAuthenticated will always be false without proper setup
    }
}
```

The problem?

Your Blazor WASM app has no built-in session management.

It's just static files served to the browser.

Authentication state lives on the server, but your UI needs to know about it.

```text
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Identity.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore;
using Backend;

var builder = WebApplication.CreateBuilder(args);

// 1. Establish cookie authentication
builder.Services.AddAuthentication(IdentityConstants.ApplicationScheme)
    .AddIdentityCookies();

// 2. Add the database (in-memory for demo, use real DB in production)
builder.Services.AddDbContext<AppDbContext>(options =>
    options.UseInMemoryDatabase("AppDb"));

// 3. Add Identity and opt-in to endpoints
builder.Services.AddIdentityCore<AppUser>()
    .AddRoles<IdentityRole>()
    .AddEntityFrameworkStores<AppDbContext>()
    .AddApiEndpoints();

// 4. Configure CORS for the Blazor WASM client

builder.Services.AddCors(options => options.AddPolicy(
    "wasm",
    policy => policy
        .WithOrigins([
            builder.Configuration["BackendUrl"] ?? "https://localhost:5001",
            builder.Configuration["FrontendUrl"] ?? "https://localhost:5002"
        ])
        .AllowAnyMethod()
        .AllowAnyHeader()
        .AllowCredentials())); // Critical for cookies!

// 5. Add authorization
builder.Services.AddAuthorizationBuilder();

var app = builder.Build();

// 6. Map Identity API endpoints
app.MapIdentityApi<AppUser>();

// 7. Activate CORS (must come before auth middleware)
app.UseCors("wasm");

// 8. Enable authentication and authorization
app.UseAuthentication();
app.UseAuthorization();

// 9. Custom logout

endpoint
app.MapPost("/logout", async (
    SignInManager<AppUser> signInManager,
    [FromBody] object empty) =>
{
    if (empty is not null)
    {
        await signInManager.SignOutAsync();
        return Results.Ok();
    }
    return Results.Unauthorized();
}).RequireAuthorization();

// 10. Custom roles endpoint
app.MapGet("/roles", (ClaimsPrincipal user) =>
{
    if (user.Identity is not null && user.Identity.IsAuthenticated)
    {
        var identity = (ClaimsIdentity)user.Identity;
        var roles = identity.FindAll(identity.RoleClaimType)
            .Select(c => new
            {
                c.Issuer,
                c.OriginalIssuer,
                c.Type,
                c.Value,
                c.ValueType
            });
        return TypedResults.Json(roles);
    }
    return Results.Unauthorized();
}).RequireAuthorization();

app.Run();

// Identity database context

class AppDbContext(DbContextOptions<AppDbContext> options) 
    : IdentityDbContext<AppUser>(options)
{
}
```

