// Builder Interface
public interface ICarBuilder
{
    void BuildEngine();
    void BuildFrame();
}

// Concrete Builders
public class BMWBuilder : ICarBuilder
{
    private Car _car;

    public BMWBuilder()
    {
        _car = new Car("BMW");
    }

    public void BuildEngine()
    {
        _car.AddPart("High-performance BMW Engine");
    }

    public void BuildFrame()
    {
        _car.AddPart("Sturdy BMW Frame");
    }
}

public class MiniBuilder : ICarBuilder
{
    private Car _car;

    public MiniBuilder()
    {
        _car = new Car("Mini");
    }

    public void BuildEngine()
    {
        _car.AddPart("Efficient Mini Engine");
    }

    public void BuildFrame()
    {
        _car.AddPart("Compact Mini Frame");
    }
}

// Product
public class Car
{
    private string _type;
    private List<string> _parts = new List<string>();

    public Car(string type)
    {
        _type = type;
    }

    public void

AddPart(string part)
    {
        _parts.Add(part);
    }

    public override string ToString()
    {
        return $"{_type} - Parts: {string.Join(", ", _parts)}";
    }
}

// Director
public class Garage
{
    private ICarBuilder _builder;

    public void Construct(ICarBuilder builder)
    {
        _builder = builder;
        _builder.BuildEngine();
        _builder.BuildFrame();
    }
}
```

In the above code, Builder Interface is an abstract interface defining the creation of parts for the product object.

In our analogy, this is akin to a car builder interface, outlining methods like buildEngine and buildFrame.

Concrete Builders is an Implementations of the builder interface, such as the BMW and Mini builders.

These class'es assemble the product and keep track of its representation, providing a method to retrieve the final product.

Product is the complex object under construction, represented by the car in our example.

It may include constituent parts like a frame or an engine.

Director is the entity responsible for constructing the object using the builder interface.

