order.UpdateTotalAmount();
subscription.ModifyEndDate(DateTime.UtcNow.AddMonths(1));

// GOOD: Intent-revealing names
customer.MarkAsPreferred();
order.RecalculateTotal();
subscription.ExtendByOneMonth();
