The above code snippets demonstrate how you can enforce architectural rules using NetArchTest.

By defining rules that align with your architectural vision, you can ensure that your software remains consistent and resilient.

Whether you're enforcing the REPR pattern in your endpoints, validating Clean Architecture principles, or enforcing encapsulation in domain entities, NetArchTest provides a robust mechanism to safeguard your architectural integrity.

But sometimes it will be difficult to debug these test to understand which class is making the violations.

To identify them easily you can use the below policy extension to report and write failures to Test Output Logs.

```text
using System.Diagnostics.CodeAnalysis;
using FluentAssertions;
using FluentAssertions.Execution;
using NetArchTest.Rules.Policies;
using Xunit.Abstractions;

namespace ILoveDotNet.FitnessTest;

[ExcludeFromCodeCoverage]
public static class PolicyExtensions
{
    public static void Report(this PolicyResults results, ITestOutputHelper output)
    {
        if (results.HasViolations)
        {
            output.WriteLine($"Policy violations found for: {results.Name}");

            foreach (var rule in results.Results)
            {
                if (rule.IsSuccessful)
                {
                    continue;
                }
                output.WriteLine("-----------------------------------------------------------");
                output.WriteLine($"Rule failed: {rule.Name}");

                foreach (var type in

rule.FailingTypes)
                {
                    output.WriteLine($"\t {type.FullName}");
                }
            }

            output.WriteLine("-----------------------------------------------------------");
        }
        else
        {
            output.WriteLine($"No policy violations found for: {results.Name}");
        }

        using var scope = new AssertionScope();
        results.HasViolations.Should().BeFalse();
    }
}
