        var filePath = Path.Combine(_storagePath, fileMetadata.StoredFileName);
        var fullPath = Path.GetFullPath(filePath);
        var fullStoragePath = Path.GetFullPath(_storagePath);

        if (!fullPath.StartsWith(
            fullStoragePath, 
