        {
            _logger.LogError(
                "Path validation failed. FileId: {FileId}",
                fileId
            );
            return StatusCode(500,

"Security error");
        }

        // Layer 4: File existence check
        if (!System.IO.File.Exists(fullPath))
        {
            _logger.LogError(
