    Task<IReadOnlyList<TResult>> ListAsync<TResult>(ISpecification<T, TResult> spec, CancellationToken cancellationToken = default);
}

public interface IAsyncRepository<T> : IAsyncReadRepository<T> where T : class
{
    Task<T> AddAsync(T entity, CancellationToken cancellationToken = default);
    Task<IEnumerable<T>> AddRangeAsync(IEnumerable<T> entity, CancellationToken cancellationToken = default);
    Task<IDbContextTransaction> BeginTransactionAsync(CancellationToken cancellationToken = default);
    void CommitTransaction();
    Task<int> ExecuteSqlRawAsync(string sql, CancellationToken cancellationToken = default);
    Task<T> FirstAsync(ISpecification<T> spec, CancellationToken cancellationToken = default);
    void Remove(T entity);
    void

RemoveRange(IEnumerable<T> entity);
    void RollbackTransaction();
    Task<Result> SaveChangesAsync(CancellationToken cancellationToken = default);
    T Update(T entity);
    void UpdateRange(IEnumerable<T> entity);
}
```

Now, if a service only needs to read data, it can depend on IAsyncReadRepository<T> and ignore all the write and transaction methods.

This makes your code more modular, easier to test, and easier to maintain.

If you need full CRUD operations, you can use IAsyncRepository<T> which includes both read and write methods.

A dependency is an object that another object depends on.

Examine the following ClassB class with that other classes depend on:

```text
public class ClassB 
{
  // omitted for brevity
} 
```

A class can create an instance of the ClassB class to make use of it.

In the following example, the ClassB class is a dependency of the ClassA class:

```text
public class ClassA
{
    private readonly ClassB _classB = new();

    public void Run()
    {
        // omitted for brevity
    }
}
```

The class creates and directly depends on the ClassB class.

Hard-coded dependencies, such as in the previous example, are problematic and should be avoided for the following reasons:

To replace ClassB with a different implementation, the ClassA class must be modified.

If ClassB has dependencies, they must also be configured by the ClassA class.

In a large project with multiple classes depending on ClassB, the configuration code becomes scattered across the app.

This implementation is difficult to unit test.

The app should use a mock or stub ClassB class, which isn't possible with this approach.

So let's try to get the instance of ClassB from constructor of ClassA.

```text
public class ClassA
{
    private readonly ClassB _classB;

    ClassA(ClassB classB)
    {
        _classB = classB;
    }

    public void Run()
    {
        // omitted for brevity
    }
}
```

Here is the complete wire up in Program.cs.

```text
class Program
{
    var classB = new ClassB();
    var classA = new ClassA(classB);

    classA.Run();
}
```

Dependency injection addresses these problems through:

The use of an interface or base class to abstract the dependency implementation.

Registration of the dependency in a service container.

.NET provides a built-in service container, IServiceProvider.

Services are typically registered at the app's start-up and appended to an IServiceCollection.

Once all services are added, you use BuildServiceProvider to create the service container.

Injection of the service into the constructor of the class where it's used.

The framework takes on the responsibility of creating an instance of the dependency and disposing of it when it's no longer needed.

```text
class Program
{
    using var host = Host.CreateDefaultBuilder(args)
                         .ConfigureServices((context, services) => 
                         { 
                             services.AddTransient<ClassB>();
                             services.AddTransient<ClassA>();
                         })
                         .Build();

    var classA = host.Services.GetRequiredService<ClassA>();
    classA.Run();
}
```

