Let's take a quick comparison of SQL, loops, and LINQ.

SQL is very similar to the LINQ query language, so we're going to take a look at SQL, looping, and LINQ all side by side.

Let's start out with a simple SQL WHERE clause.

```text
//SQL
//SELECT * from Products where the Price field is greater than 1000

//C# Loop
List<Product> products = GetProducts();
List<Product> filteredProducts = new();

foreach (var product in products)
{
  if (product.Price > 1000)
  {
    filteredProducts.Add(product);
  }
}

//C# LINQ Where Clause
List<Product> products = GetProducts();
//Method Syntax
var filteredProducts = products.Where(product => product.Price > 1000).ToList();
//Query Syntax
var filteredProducts = (from product in products
                        where product.Price > 1000
                        select product).ToList();
```

```text
//SQL
//SELECT MIN(Price) from Products

//C# Loop
List<Product> products = GetProducts();
decimal ret = decimal.MaxValue;

foreach (var product in products)
{
  if (product.Price < ret)
  {
    ret = product.Price;
  }
}

//C# LINQ Where Clause
List<Product> products = GetProducts();
//Method Syntax
var ret = products.Min(product => product.Price);
//Query Syntax
var ret = (from product in products
           select product).Min();
```

Suppose we have a base class called Vehicle, which has a method Move() that receives a key to start the vehicle.

We also have a subclass called Truck, which inherits from Vehicle.

Both classes have a method with the same signature, but their implementations may differ.

```text
public class Vehicle
{
    public virtual void Move(string key)
    {
        // Implementation to start the vehicle
    }
}

public class Truck : Vehicle
{
    public override void Move(string key)
    {
        // Implementation specific to trucks
    }
}
```

The Liskov Substitution Principle ensures that we can replace an instance of Truck with an instance of Vehicle and still expect the same behavior.

Let's see how this works:

```text
Vehicle vehicle = new Truck();
vehicle.Move("start");
```

Even though the Vehicle object is of type Truck, we can treat it as an instance of Vehicle and call the Move() method.

This demonstrates the substitutability aspect of the Liskov Substitution Principle.

Let's create a custom converter that serializes DateTimeOffset values with only the date portion (removing the time component).

This is useful when you want consistent date-only formatting.

Here's how to build it:

```text
public class DateTimeOffsetJsonConverter : JsonConverter<DateTimeOffset>
{
    public override DateTimeOffset Read(
        ref Utf8JsonReader reader, 
        Type typeToConvert, 
        JsonSerializerOptions options)
    {
        var dateString = reader.GetString();
        return DateTimeOffset.Parse(dateString!);
    }

    public override void Write(
        Utf8JsonWriter writer, 
        DateTimeOffset value, 
        JsonSerializerOptions options)
    {
        // Write only the date portion, removing time
        writer.WriteStringValue(value.ToString("yyyy-MM-dd"));
    }
}
```

Notice how the converter derives from JsonConverter<DateTimeOffset>.

There are two ways to register your custom converter.

The first is using JsonSerializerOptions:

```text
var options = new JsonSerializerOptions
{
    Converters = { new DateTimeOffsetJsonConverter() }
};

var json = JsonSerializer.Serialize(weatherForecast, options);
```

The second approach uses the [JsonConverter] attribute directly on properties or classes:

```text
public class WeatherForecast
{
    [JsonConverter(typeof(DateTimeOffsetJsonConverter))]
    public DateTimeOffset Date { get; set; }

    public int TemperatureCelsius { get; set; }
    public string? Summary { get; set; }
}
```

You can also apply [JsonConverter] to the entire class:

```text
[JsonConverter(typeof(WeatherForecastConverter))]
public class WeatherForecast
{
    // Properties...
}
```

Both methods work perfectly.

Use the attribute approach when the converter is tightly coupled to a specific property or type.

```text
public class DictionaryTKeyEnumTValueConverter : JsonConverterFactory
{
    public override bool CanConvert(Type typeToConvert)
    {
        // Only handle Dictionary<TKey, TValue> where TKey is an Enum
        if (!typeToConvert.IsGenericType)
            return false;

        if (typeToConvert.GetGenericTypeDefinition() != typeof(Dictionary<,>))
            return false;

        // Check if the key type is an Enum
        return typeToConvert.GetGenericArguments()[0].IsEnum;
    }

    public override JsonConverter CreateConverter(
        Type typeToConvert, 
        JsonSerializerOptions options)
    {
        Type keyType = typeToConvert.GetGenericArguments()[0];
        Type valueType = typeToConvert.GetGenericArguments()[1];

        JsonConverter converter = (JsonConverter)Activator.CreateInstance(

typeof(DictionaryEnumConverterInner<,>)
                .MakeGenericType(new Type[] { keyType, valueType }),
            BindingFlags.Instance | BindingFlags.Public,
            binder: null,
            args: new object[] { options },
            culture: null)!;

        return converter;
    }

    private class DictionaryEnumConverterInner<TKey, TValue> 
        : JsonConverter<Dictionary<TKey, TValue>> 
        where TKey : struct, Enum
    {
        private readonly JsonConverter<TValue> _valueConverter;
        private readonly Type _valueType;

        public DictionaryEnumConverterInner(JsonSerializerOptions options)
        {
            _valueConverter = (JsonConverter<TValue>)options
                .GetConverter(typeof(TValue));
            _valueType = typeof(TValue);
        }

        public override Dictionary<TKey, TValue> Read(
            ref Utf8JsonReader reader, 
            Type typeToConvert,

JsonSerializerOptions options)
        {
            if (reader.TokenType != JsonTokenType.StartObject)
                throw new JsonException();

            var dictionary = new Dictionary<TKey, TValue>();

            while (reader.Read())
            {
                if (reader.TokenType == JsonTokenType.EndObject)
                    return dictionary;

                string? keyString = reader.GetString();
                TKey key = Enum.Parse<TKey>(keyString!);

                reader.Read();
                TValue value = _valueConverter.Read(
                    ref reader, 
                    _valueType, 
                    options)!;

                dictionary.Add(key, value);
            }

            throw new JsonException();
        }

        public override void Write(
            Utf8JsonWriter writer, 
            Dictionary<TKey, TValue> dictionary, 
            JsonSerializerOptions options)
        {
            writer.WriteStartObject();

            foreach (KeyValuePair<TKey, TValue> kvp in dictionary)
            {
                string propertyName =

kvp.Key.ToString();
                writer.WritePropertyName(propertyName);

                // Custom transformation: modify the sentence
                if (kvp.Value is string sentence)
                {
                    string modified = ModifySentence(propertyName, sentence);
                    writer.WriteStringValue(modified);
                }
                else
                {
                    _valueConverter.Write(writer, kvp.Value, options);
                }
            }

            writer.WriteEndObject();
        }

        private string ModifySentence(string location, string sentence)
        {
            // Transform "I am from Costa Rica. This guy is freezing"
            // to "Costa Rica: This guy is freezing"
            if (sentence.StartsWith("I am from "))
            {
                var parts = sentence.Split(". ");
                if (parts.Length >= 2)
                {
                    return $"{location}: {parts[1]}";
                }
            }
            return sentence;
        }
    }
}
```

