namespace ILoveDotNet.HostedServices;

public class DataMigrationService : BackgroundService
{
    private readonly DataMigrationChannel dataMigrationChannel;
    private readonly ILogger<DataMigrationService> logger;
    private readonly IServiceProvider serviceProvider;

    public DataMigrationService(
        DataMigrationChannel dataMigrationChannel,
        ILogger<DataMigrationService> logger,
        IServiceProvider serviceProvider)
    {
        this.dataMigrationChannel = dataMigrationChannel;
        this.logger = logger;
        this.serviceProvider = serviceProvider;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        using var scope = serviceProvider.CreateScope();
        var unitOfWork = scope.ServiceProvider.GetRequiredService<IUnitOfWork>();

        await foreach (var start in dataMigrationChannel
                                       .ReadAllAsync(stoppingToken)

.WithCancellation(stoppingToken))
        {
            logger.LogInformation("Starting Data Migration");

            try
            {
                // do migration via unit of work...
            }
            catch (Exception ex)
            {
                logger.LogCritical("Data Migration Failed...");
            }

            logger.LogInformation("Data Migration Completed Successfully");
        }
    }
}
