    public async Task<T?> GetOrSetAsync<T>(string key, 
        Func<Task<T>> factory, TimeSpan expiration)
    {
        // Try to get from Redis
        var cachedData = await _cache.GetStringAsync(key);
        if (cachedData != null)
        {
